docutils.writers.odf_odt.__init__.fix_ns:
def fix_ns(tag, attrib, nsdict):
    nstag = add_ns(tag, nsdict)
    nsattrib = {}
    for (key, val) in list(attrib.items()):
        nskey = add_ns(key, nsdict)
        nsattrib[nskey] = val
    return (nstag, nsattrib)

docutils.writers.odf_odt.prepstyles.prep:
def prepstyle(filename) -> None:
    zin = zipfile.ZipFile(filename)
    styles = zin.open('styles.xml')
    root = None
    for (event, elem) in ET.iterparse(styles, events=('start', 'start-ns')):
        if event == 'start-ns':
            ET.register_namespace(elem[0], elem[1])
        elif event == 'start':
            if root is None:
                root = elem
    styles.close()
    for el in root.findall('.//style:page-layout-properties', namespaces=NAMESPACES):
        for attr in list(el.attrib):
            if attr.startswith('{%s}' % NAMESPACES['fo']):
                del el.attrib[attr]
    tempname = mkstemp()
    zout = zipfile.ZipFile(os.fdopen(tempname[0], 'wb'), 'w', zipfile.ZIP_DEFLATED)
    for item in zin.infolist():
        if item.filename == 'styles.xml':
            zout.writestr(item, ET.tostring(root, encoding='UTF-8'))
        else:
            zout.writestr(item, zin.read(item.filename))
    zout.close()
    zin.close()
    shutil.move(tempname[1], filename)

docutils.utils.__init__.escape2null:
def escape2null(text: str) -> str:
    """Return a string with escape-backslashes converted to nulls."""
    parts = []
    start = 0
    while True:
        bs_index = text.find('\\', start)
        if bs_index == -1:
            parts.append(text[start:])
            return ''.join(parts)
        parts.extend((text[start:bs_index], '\x00' + text[bs_index + 1:bs_index + 2]))
        start = bs_index + 2

docutils.parsers.docutils_xml.element2no:
def element2node(element, document=None, unindent=True):
    """
    Convert an `etree` element and its children to Docutils doctree nodes.

    :element:  `xml.etree` element
    :document: see `parse_element()`
    :unindent: Remove formatting indentation of follow-up text lines?
               Cf. `append_text()`.
               TODO: do we need an "unindent" configuration setting?

    Return a `docutils.nodes.Element` instance.

    Internal.
    """
    if document is None:
        document = utils.new_document('xml input', frontend.get_default_settings(Parser))
        document.source == 'xml input'
    if element is None:
        problem = nodes.problematic('', 'No XML element found.')
        return nodes.paragraph('', '', problem)
    try:
        nodeclass = getattr(nodes, element.tag)
        if not issubclass(nodeclass, nodes.Element):
            nodeclass = Unknown
    except AttributeError:
        nodeclass = Unknown
    if nodeclass == nodes.document:
        node = document
        document.source = (document.source or document.settings._source)
    else:
        node = nodeclass()
    node.line = int(element.get('source line'))
    if isinstance(node, Unknown):
        node.tagname = element.tag
        document.reporter.warning(f'Unknown element type <{element.tag}>.', base_node=node)
    for (key, value) in element.items():
        if (key.startswith('{') or key == 'source line'):
            continue
        try:
            node.attributes[key] = nodes.ATTRIBUTE_VALIDATORS[key](value)
        except (ValueError, KeyError):
            if key in node.list_attributes:
                value = value.split()
            node.attributes[key] = value
    if isinstance(node, nodes.decoration):
        document.decoration = node
    elif isinstance(node, nodes.substitution_definition):
        document.note_substitution_def(node, ' '.join(node['names']), document)
    if node['ids']:
        document.set_id(node)
    unindent = (unindent and not isinstance(node, (nodes.FixedTextElement, nodes.literal, Unknown)))
    append_text(node, element.text, unindent)
    for child in element:
        node.append(element2node(child, document, unindent))
        append_text(node, child.tail, unindent)
    return node

docutils.utils.__init__.extract_name_val:
def extract_name_value(line):
    """
    Return a list of (name, value) from a line of the form "name=value ...".

    :Exception:
        `NameValueError` for invalid input (missing name, missing data, bad
        quotes, etc.).
    """
    attlist = []
    while line:
        equals_index = line.find('=')
        if equals_index == -1:
            raise NameValueError('missing "="')
        attname = line[:equals_index].strip()
        if (equals_index == 0 or not attname):
            raise NameValueError('missing attribute name before "="')
        line = line[equals_index + 1:].lstrip()
        if not line:
            raise NameValueError(f'missing value after "{attname}="')
        if line[0] in '\'"':
            endquote_index = line.find(line[0], 1)
            if endquote_index == -1:
                raise NameValueError(f'attribute "{attname}" missing end quote ({line[0]})')
            if (len(line) > endquote_index + 1 and line[endquote_index + 1].strip()):
                raise NameValueError(f'attribute "{attname}" end quote ({line[0]}) not followed by whitespace')
            data = line[1:endquote_index]
            line = line[endquote_index + 1:].lstrip()
        else:
            space_index = line.find(' ')
            if space_index == -1:
                data = line
                line = ''
            else:
                data = line[:space_index]
                line = line[space_index + 1:].lstrip()
        attlist.append((attname.lower(), data))
    return attlist

docutils.parsers.rst.directives.__init__:
def single_char_or_whitespace_or_unicode(argument: str) -> str:
    """
    As with `single_char_or_unicode`, but "tab" and "space" are also supported.
    (Directive option conversion function.)
    """
    if argument == 'tab':
        char = '\t'
    elif argument == 'space':
        char = ' '
    else:
        char = single_char_or_unicode(argument)
    return char

docutils.writers.odf_odt.__init__.SubEle:
def SubElement(parent, tag, attrib=None, nsmap=None, nsdict=CNSD):
    if attrib is None:
        attrib = {}
    (tag, attrib) = fix_ns(tag, attrib, nsdict)
    el = _ElementInterfaceWrapper(tag, attrib)
    parent.append(el)
    el.setparent(parent)
    return el

docutils.frontend.read_config_file:
def read_config_file(option: optparse.Option, opt: str, value: Any, parser: OptionParser) -> None:
    """
    Read a configuration file during option processing.  (Option callback.)

    Deprecated. Will be removed with the switch to from optparse to argparse.
    """
    try:
        new_settings = parser.get_config_file_settings(value)
    except ValueError as err:
        parser.error(err)
    parser.values.update(new_settings, parser)
